package com.unicarona.privacy.service;

import org.springframework.boot.*;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

/** No API or worker processing opens before the independent suppression journal has been applied. */
@Component @Order(100)
public class PrivacyRestoreGuard implements ApplicationRunner {
    private final PrivacyErasureJournal journal;private final PrivacyErasureMaintenance erasure;private final PrivacyReadiness readiness;private final PrivacyRestoreFence fence;private final PrivacyFileErasure files;private final PrivacyLocationRetentionTransactions locations;private final PrivacyHoldRecovery holdControls;private final PrivacyOrphanFileTransactions orphans;private final PrivacyDriverDocumentsMaintenance driverDocuments;private final PrivacyDriverApplicationMaintenance driverApplications;private final PrivacyCheckoutMaintenance checkout;private final PrivacySecurityAuditMaintenance securityAudit;private final PrivacyRetentionTransactions evidenceRetention;private final PrivacyUnsubmittedCheckoutMaintenance unsubmitted;private final PrivacyFailedTransferMaintenance failedTransfers;private final PrivacyBoardingPinMaintenance boardingPins;private final PrivacyTripDetailsMaintenance tripDetails;
    public PrivacyRestoreGuard(PrivacyErasureJournal journal,PrivacyErasureMaintenance erasure,PrivacyReadiness readiness,PrivacyRestoreFence fence,PrivacyFileErasure files,PrivacyLocationRetentionTransactions locations,PrivacyHoldRecovery holdControls,PrivacyOrphanFileTransactions orphans,PrivacyDriverDocumentsMaintenance driverDocuments,PrivacyDriverApplicationMaintenance driverApplications,PrivacyCheckoutMaintenance checkout,PrivacySecurityAuditMaintenance securityAudit,PrivacyRetentionTransactions evidenceRetention,PrivacyUnsubmittedCheckoutMaintenance unsubmitted,PrivacyFailedTransferMaintenance failedTransfers,PrivacyBoardingPinMaintenance boardingPins,PrivacyTripDetailsMaintenance tripDetails){this.journal=journal;this.erasure=erasure;this.readiness=readiness;this.fence=fence;this.files=files;this.locations=locations;this.holdControls=holdControls;this.orphans=orphans;this.driverDocuments=driverDocuments;this.driverApplications=driverApplications;this.checkout=checkout;this.securityAudit=securityAudit;this.evidenceRetention=evidenceRetention;this.unsubmitted=unsubmitted;this.failedTransfers=failedTransfers;this.boardingPins=boardingPins;this.tripDetails=tripDetails;}
    @Override public void run(ApplicationArguments args)throws Exception {
        readiness.begin();var entries=journal.entries();fence.checkBeforeReplay();holdControls.beforeReadiness();driverDocuments.beforeReadiness();for(var entry:entries)erasure.replay(entry);for(var entry:journal.fileEntries())files.replay(entry);for(var entry:journal.orphanEntries())orphans.replay(entry);erasure.suppressRecordedFilesBeforeReadiness();locations.suppressBeforeReadiness();driverApplications.beforeReadiness();checkout.beforeReadiness();securityAudit.beforeReadiness();evidenceRetention.beforeReadiness();unsubmitted.beforeReadiness();failedTransfers.beforeReadiness();boardingPins.beforeReadiness();tripDetails.beforeReadiness();fence.markObserved();readiness.complete();
    }
}
